Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" Availability : specifies
TutoringOffer "*" -- "1" Subject : for
TutoringOffer "*" -- "1" ExpertiseLevel : at
TutoringOffer "*" -- "1" Tutor : by
TutoringRequest "1" -- "1" TutoringSession : results in
